import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def calculate_ratio(n):
    if n < 3:
        return None # f(K_n) is zero or ill-defined

    f_kn = combinations(n, 3)
    g_kn = combinations(n, 4)

    # Check for division by zero, although for n >= 3, f_kn >= 1
    if f_kn == 0:
        return None

    ratio = (g_kn**3) / (f_kn**4)
    return ratio

results = {}
for n in range(1, 11):
    ratio = calculate_ratio(n)
    if ratio is not None:
        results[n] = ratio

print("Ratio g(K_n)^3 / f(K_n)^4 for n=1 to 10:")
for n, ratio in results.items():
    print(f"n={n}: {ratio}")

# Find the maximum observed ratio
max_ratio = 0
for ratio in results.values():
    if ratio > max_ratio:
        max_ratio = ratio

print(f"\nMaximum observed ratio for n=3 to 10: {max_ratio}")
